//! The Rust types agree with the JSON Schemas in both directions: every valid example
//! deserialises into its Rust type (which refuses unknown fields) and serialises back to the
//! same JSON, and every event example's identity and every backup line's checksum are what
//! this crate computes. The examples were generated by a separate implementation, so the
//! identity check is also a cross-check of the canonical JSON.

mod common;

use common::good_examples;
use issue_dashboard_core::backup::{Line, checksum};
use issue_dashboard_core::config::{Project, Registry, RepoFile};
use issue_dashboard_core::decision::DecidedData;
use issue_dashboard_core::docs::{Decision, LaunchRequest};
use issue_dashboard_core::event::{Event, Kind};
use issue_dashboard_core::launch::LaunchData;
use issue_dashboard_core::observe::ObservedData;
use issue_dashboard_core::outcome::Outcome;
use serde::Serialize;
use serde::de::DeserializeOwned;
use serde_json::Value;

/// Deserialises `value` into `T` and checks it serialises back to the same JSON.
fn round_trip<T: DeserializeOwned + Serialize>(what: &str, value: &Value) {
    let typed: T =
        serde_json::from_value(value.clone()).unwrap_or_else(|e| panic!("{what} does not deserialise: {e}\n{value:#}"));
    let back = serde_json::to_value(&typed).unwrap();
    assert_eq!(&back, value, "{what} does not round-trip");
}

#[test]
fn config_examples_parse_into_the_config_types() {
    for (name, v) in good_examples("config-registry") {
        round_trip::<Registry>(&name, &v);
    }
    for (name, v) in good_examples("config-project") {
        round_trip::<Project>(&name, &v);
    }
    for (name, v) in good_examples("config-repo-file") {
        round_trip::<RepoFile>(&name, &v);
    }
}

#[test]
fn bad_config_examples_with_unknown_keys_are_refused_by_the_types_too() {
    for (stem, file) in [
        ("config-registry", "bad-unknown-key.toml"),
        ("config-repo-file", "bad-unknown-key.toml"),
    ] {
        let path = common::schemas_dir().join("examples").join(stem).join(file);
        let text = std::fs::read_to_string(&path).unwrap();
        let refused = if stem == "config-registry" {
            toml::from_str::<Registry>(&text).is_err()
        } else {
            toml::from_str::<RepoFile>(&text).is_err()
        };
        assert!(refused, "{stem}/{file} parsed although it has an unknown key");
    }
}

#[test]
fn page_document_examples_parse_into_the_document_types() {
    for (name, v) in good_examples("page-decision") {
        round_trip::<Decision>(&name, &v);
    }
    let mut requests = 0;
    for (name, v) in good_examples("page-launch") {
        // not_sent records and the thread document are page bookkeeping, not launch requests.
        if v.get("kind").is_some() {
            round_trip::<LaunchRequest>(&name, &v);
            requests += 1;
        }
    }
    assert!(requests >= 1, "no launch request example was checked");
}

#[test]
fn event_examples_have_the_identity_this_crate_computes_and_typed_data() {
    let mut checked = 0;
    for stem in [
        "event-config",
        "event-observed",
        "event-item-gone",
        "event-decided",
        "event-view-saved",
        "event-request",
        "event-suggested",
        "event-launch",
        "event-outcome",
        "event-exported",
        "event",
    ] {
        for (name, v) in good_examples(stem) {
            let what = format!("{stem}/{name}");
            let event: Event = serde_json::from_value(v.clone()).unwrap_or_else(|e| panic!("{what}: {e}"));
            assert_eq!(event.identity, event.computed_identity(), "{what}: identity");
            match event.kind {
                Kind::Launch => round_trip::<LaunchData>(&what, &event.data),
                Kind::Outcome => round_trip::<Outcome>(&what, &event.data),
                Kind::Decided => round_trip::<DecidedData>(&what, &event.data),
                Kind::Observed => round_trip::<ObservedData>(&what, &event.data),
                _ => {}
            }
            checked += 1;
        }
    }
    assert!(checked >= 18, "only {checked} event examples checked");
}

#[test]
fn ledger_line_examples_carry_the_checksum_this_crate_computes() {
    for (name, v) in good_examples("ledger-line") {
        let line: Line = serde_json::from_value(v).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(line.checksum, checksum(&line.event), "{name}");
    }
}
